window.NCERT_CLOZE_DATA["Microbes_in_Human_Welfare_Zoo"] = {"id": "Microbes_in_Human_Welfare_Zoo", "title": "Microbes in Human Welfare", "subject": "Zoology", "class": "Class 12", "chapter_no": 10, "stats": {"sentences": 199, "blanks": 137, "skipped_sentences": 103, "elements": 216}, "elements": [{"type": "h4", "content": "Chapter 10"}, {"type": "h2", "content": "Microbes in Human Welfare"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s1", "tokens": [{"t": "text", "v": "10.1 Microbes in Household Products"}], "blanks": [], "text": "10.1 Microbes in Household Products"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s2", "tokens": [{"t": "text", "v": "10.2 Microbes in Industrial Products"}], "blanks": [], "text": "10.2 Microbes in Industrial Products"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s3", "tokens": [{"t": "text", "v": "10.3 Microbes in Sewage Treatment"}], "blanks": [], "text": "10.3 Microbes in Sewage Treatment"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s4", "tokens": [{"t": "text", "v": "10.4 Microbes in Production of Biogas"}], "blanks": [], "text": "10.4 Microbes in Production of Biogas"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s5", "tokens": [{"t": "text", "v": "10.5 Microbes as Biocontrol Agents"}], "blanks": [], "text": "10.5 Microbes as Biocontrol Agents"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s6", "tokens": [{"t": "text", "v": "10.6 Microbes as Biofertilisers"}], "blanks": [], "text": "10.6 Microbes as Biofertilisers"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s7", "tokens": [{"t": "text", "v": "Besides macroscopic plants and animals, microbes are the major components of biological systems on this earth."}], "blanks": [], "text": "Besides macroscopic plants and animals, microbes are the major components of biological systems on this earth."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s8", "tokens": [{"t": "text", "v": "You have studied about the diversity of living organisms in Class XI."}], "blanks": [], "text": "You have studied about the diversity of living organisms in Class XI."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s9", "tokens": [{"t": "text", "v": "Do you remember which Kingdoms among the living organisms contain micro-organisms?"}], "blanks": [], "text": "Do you remember which Kingdoms among the living organisms contain micro-organisms?"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s10", "tokens": [{"t": "text", "v": "Which are the ones that are only microscopic?"}], "blanks": [], "text": "Which are the ones that are only microscopic?"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s11", "tokens": [{"t": "text", "v": "Microbes are present everywher e – in soil, water, air, inside our bodies and that of other animals and plants."}], "blanks": [], "text": "Microbes are present everywher e – in soil, water, air, inside our bodies and that of other animals and plants."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s12", "tokens": [{"t": "text", "v": "They are present even at sites where no other life-form could possibly exis t – sites such as deep inside the geysers (thermal vents) where the temperature may be as high as 100 0 C, deep in the soil, under the layers of snow several metr es thick, and in highly acidic environments."}], "blanks": [], "text": "They are present even at sites where no other life-form could possibly exis t – sites such as deep inside the geysers (thermal vents) where the temperature may be as high as 100 0 C, deep in the soil, under the layers of snow several metr es thick, and in highly acidic environments."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s13", "tokens": [{"t": "text", "v": "Microbes are divers e – protozoa, bacteria, fungi and microscopic animal and plant viruses, "}, {"t": "cloze", "v": "viroids"}, {"t": "text", "v": " and also "}, {"t": "cloze", "v": "prions"}, {"t": "text", "v": " that are proteinacious infectious agents."}], "blanks": ["viroids", "prions"], "text": "Microbes are divers e – protozoa, bacteria, fungi and microscopic animal and plant viruses, viroids and also prions that are proteinacious infectious agents."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s14", "tokens": [{"t": "text", "v": "Some of the microbes are shown in Figures 10.1 and 10.2."}], "blanks": [], "text": "Some of the microbes are shown in Figures 10.1 and 10.2."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s15", "tokens": [{"t": "text", "v": "Microbes like bacteria and many fungi can be grown on nutritive media to form "}, {"t": "cloze", "v": "colonies"}, {"t": "text", "v": " (Figure 10.3), that can be seen with the naked eyes."}], "blanks": ["colonies"], "text": "Microbes like bacteria and many fungi can be grown on nutritive media to form colonies (Figure 10.3), that can be seen with the naked eyes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s16", "tokens": [{"t": "text", "v": "Such cultures are useful in studies on micro-organisms."}], "blanks": [], "text": "Such cultures are useful in studies on micro-organisms."}, {"type": "table", "rows": [["Figure 10.1 Bacteria: (a) Rod-shaped, magnified 1500X; (b) Spherical shaped, magnified 1500X; (c) A rodshaped bacterium showing flagella, magnified 50,000X", "", "Figure 10.2 Viruses: (a) A bacteriophage; (b) Adenovirus which causes respiratory infections; (c) Rod-shaped Tobacco Mosaic Virus (TMV). Magnified about 1,00,000–1,50,000X"]]}, {"type": "caption", "content": "Figure 10.3 (a) Colonies of bacteria growing in a petri dish; (b) Fungal colony growing in a petri dish"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s17", "tokens": [{"t": "text", "v": "In chapter 8, you have read that microbes cause a large number of diseases in human beings."}], "blanks": [], "text": "In chapter 8, you have read that microbes cause a large number of diseases in human beings."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s18", "tokens": [{"t": "text", "v": "They also cause diseases in animals and plants."}], "blanks": [], "text": "They also cause diseases in animals and plants."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s19", "tokens": [{"t": "text", "v": "But this should not make you think that all microbes are harmful; several microbes are useful to man in diverse ways."}], "blanks": [], "text": "But this should not make you think that all microbes are harmful; several microbes are useful to man in diverse ways."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s20", "tokens": [{"t": "text", "v": "Some of the most important contributions of microbes to human welfare are discussed in this chapter."}], "blanks": [], "text": "Some of the most important contributions of microbes to human welfare are discussed in this chapter."}, {"type": "h3", "content": "10.1 Microbes in Household Products"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s21", "tokens": [{"t": "text", "v": "You would be surprised to know that we use microbes or products derived from them everyday."}], "blanks": [], "text": "You would be surprised to know that we use microbes or products derived from them everyday."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s22", "tokens": [{"t": "text", "v": "A common example is the production of curd from milk."}], "blanks": [], "text": "A common example is the production of curd from milk."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s23", "tokens": [{"t": "text", "v": "Micro-organisms such as "}, {"t": "cloze", "v": "Lactobacillus"}, {"t": "text", "v": " and others commonly called "}, {"t": "cloze", "v": "lactic acid bacteria (LAB)"}, {"t": "text", "v": " grow in milk and convert it to curd."}], "blanks": ["Lactobacillus", "lactic acid bacteria (LAB)"], "text": "Micro-organisms such as Lactobacillus and others commonly called lactic acid bacteria (LAB) grow in milk and convert it to curd."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s24", "tokens": [{"t": "text", "v": "During growth, the "}, {"t": "cloze", "v": "LAB"}, {"t": "text", "v": " produce acids that coagulate and partially digest the milk proteins."}], "blanks": ["LAB"], "text": "During growth, the LAB produce acids that coagulate and partially digest the milk proteins."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s25", "tokens": [{"t": "text", "v": "A small amount of curd added to the fresh milk as "}, {"t": "cloze", "v": "inoculum"}, {"t": "text", "v": " or starter contain millions of LAB, which at suitable temperatures multiply, thus converting milk to curd, which also improves its nutritional quality by increasing "}, {"t": "cloze", "v": "vitamin B 12"}, {"t": "text", "v": " ."}], "blanks": ["inoculum", "vitamin B 12"], "text": "A small amount of curd added to the fresh milk as inoculum or starter contain millions of LAB, which at suitable temperatures multiply, thus converting milk to curd, which also improves its nutritional quality by increasing vitamin B 12 ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s26", "tokens": [{"t": "text", "v": "In our stomach too, the "}, {"t": "cloze", "v": "LAB"}, {"t": "text", "v": " play very beneficial role in checking disease-causing microbes."}], "blanks": ["LAB"], "text": "In our stomach too, the LAB play very beneficial role in checking disease-causing microbes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s27", "tokens": [{"t": "text", "v": "The dough, which is used for making foods such as "}, {"t": "cloze", "v": "dosa and idl i"}, {"t": "text", "v": " is also fermented by bacteria."}], "blanks": ["dosa and idl i"], "text": "The dough, which is used for making foods such as dosa and idl i is also fermented by bacteria."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s28", "tokens": [{"t": "text", "v": "The puffed-up appearance of dough is due to the production of "}, {"t": "cloze", "v": "CO 2"}, {"t": "text", "v": " gas."}], "blanks": ["CO 2"], "text": "The puffed-up appearance of dough is due to the production of CO 2 gas."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s29", "tokens": [{"t": "text", "v": "Can you tell which metabolic pathway is taking place resulting in the formation of "}, {"t": "cloze", "v": "CO 2"}, {"t": "text", "v": " ?"}], "blanks": ["CO 2"], "text": "Can you tell which metabolic pathway is taking place resulting in the formation of CO 2 ?"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s30", "tokens": [{"t": "text", "v": "Where do you think the bacteria for these fermentations come from?"}], "blanks": [], "text": "Where do you think the bacteria for these fermentations come from?"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s31", "tokens": [{"t": "text", "v": "Similarly the dough, which is used for making bread, is fermented using "}, {"t": "cloze", "v": "baker’s yeast"}, {"t": "text", "v": " ( "}, {"t": "cloze", "v": "Saccharomyces cerevisiae"}, {"t": "text", "v": " )."}], "blanks": ["baker’s yeast", "Saccharomyces cerevisiae"], "text": "Similarly the dough, which is used for making bread, is fermented using baker’s yeast ( Saccharomyces cerevisiae )."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s32", "tokens": [{"t": "text", "v": "A number of traditional drinks and foods are also made by fermentation by the microbes."}], "blanks": [], "text": "A number of traditional drinks and foods are also made by fermentation by the microbes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s33", "tokens": [{"t": "cloze", "v": "‘Toddy’"}, {"t": "text", "v": ", a traditional drink of some parts of southern India is made by fermenting sap from palms."}], "blanks": ["‘Toddy’"], "text": "‘Toddy’, a traditional drink of some parts of southern India is made by fermenting sap from palms."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s34", "tokens": [{"t": "text", "v": "Microbes are also used to ferment fish, soyabean and bamboo-shoots to make foods."}], "blanks": [], "text": "Microbes are also used to ferment fish, soyabean and bamboo-shoots to make foods."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s35", "tokens": [{"t": "text", "v": "Cheese, is one of the oldest food items in which microbes were used."}], "blanks": [], "text": "Cheese, is one of the oldest food items in which microbes were used."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s36", "tokens": [{"t": "text", "v": "Different varieties of cheese are known by their characteristic texture, flavour and taste, the specificity coming from the microbes used."}], "blanks": [], "text": "Different varieties of cheese are known by their characteristic texture, flavour and taste, the specificity coming from the microbes used."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s37", "tokens": [{"t": "text", "v": "For example, the large holes in ‘"}, {"t": "cloze", "v": "Swiss cheese"}, {"t": "text", "v": "’ are due to production of a large amount of CO 2 by a bacterium named "}, {"t": "cloze", "v": "Propionibacterium sharmanii"}, {"t": "text", "v": " ."}], "blanks": ["Swiss cheese", "Propionibacterium sharmanii"], "text": "For example, the large holes in ‘Swiss cheese’ are due to production of a large amount of CO 2 by a bacterium named Propionibacterium sharmanii ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s38", "tokens": [{"t": "text", "v": "The "}, {"t": "cloze", "v": "‘Roquefort cheese’"}, {"t": "text", "v": " are ripened by growing a specific fungi on them, which gives them a particular flavo ur."}], "blanks": ["‘Roquefort cheese’"], "text": "The ‘Roquefort cheese’ are ripened by growing a specific fungi on them, which gives them a particular flavo ur."}, {"type": "h3", "content": "10.2 Microbes in Industrial Products"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s39", "tokens": [{"t": "text", "v": "Even in industry, microbes are used to synthesise a number of products valuable to human beings."}], "blanks": [], "text": "Even in industry, microbes are used to synthesise a number of products valuable to human beings."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s40", "tokens": [{"t": "text", "v": "Beverages and antibiotics are some examples."}], "blanks": [], "text": "Beverages and antibiotics are some examples."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s41", "tokens": [{"t": "text", "v": "Production on an industrial scale, requires growing microbes in very large vessels called "}, {"t": "cloze", "v": "fermentors"}, {"t": "text", "v": " (Figure 10.4)."}], "blanks": ["fermentors"], "text": "Production on an industrial scale, requires growing microbes in very large vessels called fermentors (Figure 10.4)."}, {"type": "h4", "content": "10 .2.1 Fermented Beverages"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s42", "tokens": [{"t": "text", "v": "Microbes especially yeasts have been used from time immemorial for the production of beverages like wine, beer, whisky, brandy or rum."}], "blanks": [], "text": "Microbes especially yeasts have been used from time immemorial for the production of beverages like wine, beer, whisky, brandy or rum."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s43", "tokens": [{"t": "text", "v": "For this purpose the same yeast "}, {"t": "cloze", "v": "Saccharomyces cerevisiae"}, {"t": "text", "v": " used for bread-making and commonly called "}, {"t": "cloze", "v": "brewer’s yeast"}, {"t": "text", "v": ", is used for fermenting malted cereals and fruit juices, to produce ethanol."}], "blanks": ["Saccharomyces cerevisiae", "brewer’s yeast"], "text": "For this purpose the same yeast Saccharomyces cerevisiae used for bread-making and commonly called brewer’s yeast, is used for fermenting malted cereals and fruit juices, to produce ethanol."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s44", "tokens": [{"t": "text", "v": "Do you recollect the metabolic reactions, which result in the production of ethanol by yeast?"}], "blanks": [], "text": "Do you recollect the metabolic reactions, which result in the production of ethanol by yeast?"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s45", "tokens": [{"t": "text", "v": "Depending on the type of the raw material used for fermentation and the type of processing (with or without distillation) different types of alcoholic drinks are obtained."}], "blanks": [], "text": "Depending on the type of the raw material used for fermentation and the type of processing (with or without distillation) different types of alcoholic drinks are obtained."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s46", "tokens": [{"t": "cloze", "v": "Wine and beer"}, {"t": "text", "v": " are produced without distillation whereas "}, {"t": "cloze", "v": "whisky, brandy and rum"}, {"t": "text", "v": " are produced by distillation of the fermented broth."}], "blanks": ["Wine and beer", "whisky, brandy and rum"], "text": "Wine and beer are produced without distillation whereas whisky, brandy and rum are produced by distillation of the fermented broth."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s47", "tokens": [{"t": "text", "v": "The photograph of a fermentation plant is shown in Figure 10.5."}], "blanks": [], "text": "The photograph of a fermentation plant is shown in Figure 10.5."}, {"type": "h4", "content": "10.2.2 Antibiotics"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s48", "tokens": [{"t": "text", "v": "Antibiotics produced by microbes are regarded as one of the most significant discoveries of the twentieth century and have greatly contributed towards the welfare of the human society."}], "blanks": [], "text": "Antibiotics produced by microbes are regarded as one of the most significant discoveries of the twentieth century and have greatly contributed towards the welfare of the human society."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s49", "tokens": [{"t": "text", "v": "Anti is a "}, {"t": "cloze", "v": "Greek word"}, {"t": "text", "v": " that means ‘against’, and bio means ‘life’, together they mean ‘against life’ (in the context of disease causing organisms); whereas with reference to human beings, they are ‘pro life’ and not against."}], "blanks": ["Greek word"], "text": "Anti is a Greek word that means ‘against’, and bio means ‘life’, together they mean ‘against life’ (in the context of disease causing organisms); whereas with reference to human beings, they are ‘pro life’ and not against."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s50", "tokens": [{"t": "cloze", "v": "Antibiotics"}, {"t": "text", "v": " are chemical substances, which are produced by some microbes and can kill or retard the growth of other (disease-causing) microbes."}], "blanks": ["Antibiotics"], "text": "Antibiotics are chemical substances, which are produced by some microbes and can kill or retard the growth of other (disease-causing) microbes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s51", "tokens": [{"t": "text", "v": "You are familiar with the commonly used antibiotic "}, {"t": "cloze", "v": "Penicillin"}, {"t": "text", "v": "."}], "blanks": ["Penicillin"], "text": "You are familiar with the commonly used antibiotic Penicillin."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s52", "tokens": [{"t": "text", "v": "Do you know that "}, {"t": "cloze", "v": "Penicillin"}, {"t": "text", "v": " was the "}, {"t": "cloze", "v": "first antibiotic"}, {"t": "text", "v": " to be discovered, and it was a chance discovery?"}], "blanks": ["Penicillin", "first antibiotic"], "text": "Do you know that Penicillin was the first antibiotic to be discovered, and it was a chance discovery?"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s53", "tokens": [{"t": "cloze", "v": "Alexander Fleming"}, {"t": "text", "v": " while working on "}, {"t": "cloze", "v": "Staphylococci"}, {"t": "text", "v": " bacteria, once observed a mould growing in one of his unwashed culture plates around which "}, {"t": "cloze", "v": "Staphylococci"}, {"t": "text", "v": " could not grow."}], "blanks": ["Alexander Fleming", "Staphylococci", "Staphylococci"], "text": "Alexander Fleming while working on Staphylococci bacteria, once observed a mould growing in one of his unwashed culture plates around which Staphylococci could not grow."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s54", "tokens": [{"t": "text", "v": "He found out that it was due to a chemical produced by the mould and he named it "}, {"t": "cloze", "v": "Penicillin"}, {"t": "text", "v": " after the mould "}, {"t": "cloze", "v": "Penicillium notatum"}, {"t": "text", "v": "."}], "blanks": ["Penicillin", "Penicillium notatum"], "text": "He found out that it was due to a chemical produced by the mould and he named it Penicillin after the mould Penicillium notatum."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s55", "tokens": [{"t": "text", "v": "However, its full potential as an effective antibiotic was established much later by "}, {"t": "cloze", "v": "Ernest Chain"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "Howard Florey"}, {"t": "text", "v": "."}], "blanks": ["Ernest Chain", "Howard Florey"], "text": "However, its full potential as an effective antibiotic was established much later by Ernest Chain and Howard Florey."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s56", "tokens": [{"t": "text", "v": "This antibiotic was extensively used to treat American soldiers wounded in World War II."}], "blanks": [], "text": "This antibiotic was extensively used to treat American soldiers wounded in World War II."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s57", "tokens": [{"t": "cloze", "v": "Fleming, Chain and Florey"}, {"t": "text", "v": " were awarded the Nobel Prize in "}, {"t": "cloze", "v": "1945"}, {"t": "text", "v": ", for this discovery."}], "blanks": ["Fleming, Chain and Florey", "1945"], "text": "Fleming, Chain and Florey were awarded the Nobel Prize in 1945, for this discovery."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s58", "tokens": [{"t": "text", "v": "After Penicillin, other antibiotics were also purified from other microbes."}], "blanks": [], "text": "After Penicillin, other antibiotics were also purified from other microbes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s59", "tokens": [{"t": "text", "v": "Can you name some other antibiotics and find out their sources?"}], "blanks": [], "text": "Can you name some other antibiotics and find out their sources?"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s60", "tokens": [{"t": "text", "v": "Antibiotics have greatly improved our capacity to treat deadly diseases such as plague, whooping cough ( kali khans i ), diphtheria ( gal ghotu ) and leprosy ( kusht rog ), which used to kill millions all over the globe."}], "blanks": [], "text": "Antibiotics have greatly improved our capacity to treat deadly diseases such as plague, whooping cough ( kali khans i ), diphtheria ( gal ghotu ) and leprosy ( kusht rog ), which used to kill millions all over the globe."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s61", "tokens": [{"t": "text", "v": "Today, we cannot imagine a world without antibiotics."}], "blanks": [], "text": "Today, we cannot imagine a world without antibiotics."}, {"type": "h4", "content": "10.2.3 Chemicals, Enzymes and other Bioactive Molecules"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s62", "tokens": [{"t": "text", "v": "Microbes are also used for commercial and industrial production of certain chemicals like organic acids, alcohols and enzymes."}], "blanks": [], "text": "Microbes are also used for commercial and industrial production of certain chemicals like organic acids, alcohols and enzymes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s63", "tokens": [{"t": "text", "v": "Examples of acid producers are "}, {"t": "cloze", "v": "Aspergillus niger"}, {"t": "text", "v": " (a fungus) of citric acid, "}, {"t": "cloze", "v": "Acetobacter aceti"}, {"t": "text", "v": " (a bacterium) of acetic acid; "}, {"t": "cloze", "v": "Clostridium butylicum"}, {"t": "text", "v": " (a bacterium) of butyric acid and Lactobacillus (a bacterium) of lactic acid."}], "blanks": ["Aspergillus niger", "Acetobacter aceti", "Clostridium butylicum"], "text": "Examples of acid producers are Aspergillus niger (a fungus) of citric acid, Acetobacter aceti (a bacterium) of acetic acid; Clostridium butylicum (a bacterium) of butyric acid and Lactobacillus (a bacterium) of lactic acid."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s64", "tokens": [{"t": "text", "v": "Yeast ( "}, {"t": "cloze", "v": "Saccharomyces cerevisiae"}, {"t": "text", "v": ") is used for commercial production of "}, {"t": "cloze", "v": "ethanol"}, {"t": "text", "v": "."}], "blanks": ["Saccharomyces cerevisiae", "ethanol"], "text": "Yeast ( Saccharomyces cerevisiae) is used for commercial production of ethanol."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s65", "tokens": [{"t": "text", "v": "Microbes are also used for production of enzymes."}], "blanks": [], "text": "Microbes are also used for production of enzymes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s66", "tokens": [{"t": "cloze", "v": "Lipases"}, {"t": "text", "v": " are used in detergent formulations and are helpful in removing oily stains from the laundry."}], "blanks": ["Lipases"], "text": "Lipases are used in detergent formulations and are helpful in removing oily stains from the laundry."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s67", "tokens": [{"t": "text", "v": "You must have noticed that bottled fruit juices bought from the market are clearer as compared to those made at home."}], "blanks": [], "text": "You must have noticed that bottled fruit juices bought from the market are clearer as compared to those made at home."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s68", "tokens": [{"t": "text", "v": "This is because the bottled juices are clarified by the use of "}, {"t": "cloze", "v": "pectinases"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "proteases"}, {"t": "text", "v": "."}], "blanks": ["pectinases", "proteases"], "text": "This is because the bottled juices are clarified by the use of pectinases and proteases."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s69", "tokens": [{"t": "cloze", "v": "Streptokinase"}, {"t": "text", "v": " produced by the bacterium "}, {"t": "cloze", "v": "Streptococcus"}, {"t": "text", "v": " and modified by genetic engineering is used as a ‘"}, {"t": "cloze", "v": "clot buster"}, {"t": "text", "v": "’ for removing clots from the blood vessels of patients who have undergone myocardial infarction leading to heart attack."}], "blanks": ["Streptokinase", "Streptococcus", "clot buster"], "text": "Streptokinase produced by the bacterium Streptococcus and modified by genetic engineering is used as a ‘clot buster’ for removing clots from the blood vessels of patients who have undergone myocardial infarction leading to heart attack."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s70", "tokens": [{"t": "text", "v": "Another bioactive molecule, "}, {"t": "cloze", "v": "cyclosporin A"}, {"t": "text", "v": ", that is used as an immunosuppressive agent in organ-transplant patients, is produced by the fungus "}, {"t": "cloze", "v": "Trichoderma polysporum"}, {"t": "text", "v": " ."}], "blanks": ["cyclosporin A", "Trichoderma polysporum"], "text": "Another bioactive molecule, cyclosporin A, that is used as an immunosuppressive agent in organ-transplant patients, is produced by the fungus Trichoderma polysporum ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s71", "tokens": [{"t": "cloze", "v": "Statins"}, {"t": "text", "v": " produced by the yeast "}, {"t": "cloze", "v": "Monascus purpureus"}, {"t": "text", "v": " have been commercialised as blood-cholesterol lowering agents."}], "blanks": ["Statins", "Monascus purpureus"], "text": "Statins produced by the yeast Monascus purpureus have been commercialised as blood-cholesterol lowering agents."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s72", "tokens": [{"t": "text", "v": "It acts by competitively inhibiting the enzyme responsible for synthesis of cholesterol."}], "blanks": [], "text": "It acts by competitively inhibiting the enzyme responsible for synthesis of cholesterol."}, {"type": "h2", "content": "10.3 Microbes in Sewage Treatment"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s73", "tokens": [{"t": "text", "v": "We know that large quantities of waste water are generated everyday in cities and towns."}], "blanks": [], "text": "We know that large quantities of waste water are generated everyday in cities and towns."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s74", "tokens": [{"t": "text", "v": "A major component of this waste water is human excreta."}], "blanks": [], "text": "A major component of this waste water is human excreta."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s75", "tokens": [{"t": "text", "v": "This municipal waste-water is also called "}, {"t": "cloze", "v": "sewage"}, {"t": "text", "v": "."}], "blanks": ["sewage"], "text": "This municipal waste-water is also called sewage."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s76", "tokens": [{"t": "text", "v": "It contains large amounts of organic matter and microbes."}], "blanks": [], "text": "It contains large amounts of organic matter and microbes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s77", "tokens": [{"t": "text", "v": "Many of which are pathogenic. Have you ever wondered where this huge quantity of sewage or urban waste water is disposed off daily?"}], "blanks": [], "text": "Many of which are pathogenic. Have you ever wondered where this huge quantity of sewage or urban waste water is disposed off daily?"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s78", "tokens": [{"t": "text", "v": "This cannot be discharged into natural water bodies like rivers and streams directly – you can understand why."}], "blanks": [], "text": "This cannot be discharged into natural water bodies like rivers and streams directly – you can understand why."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s79", "tokens": [{"t": "text", "v": "Before disposal, hence, sewage is treated in "}, {"t": "cloze", "v": "sewage treatment plants (STPs)"}, {"t": "text", "v": " to make it less polluting."}], "blanks": ["sewage treatment plants (STPs)"], "text": "Before disposal, hence, sewage is treated in sewage treatment plants (STPs) to make it less polluting."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s80", "tokens": [{"t": "text", "v": "Treatment of waste water is done by the "}, {"t": "cloze", "v": "heterotrophic microbes"}, {"t": "text", "v": " naturally present in the sewage."}], "blanks": ["heterotrophic microbes"], "text": "Treatment of waste water is done by the heterotrophic microbes naturally present in the sewage."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s81", "tokens": [{"t": "text", "v": "This treatment is carried out in two stages:"}], "blanks": [], "text": "This treatment is carried out in two stages:"}, {"type": "caption", "content": "Figure 10.6 Secondary treatment"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s82", "tokens": [{"t": "cloze", "v": "Primary treatment"}, {"t": "text", "v": " : These treatment steps basically involve "}, {"t": "cloze", "v": "physical removal"}, {"t": "text", "v": " of particles – large and small – from the sewage through filtration and sedimentation."}], "blanks": ["Primary treatment", "physical removal"], "text": "Primary treatment : These treatment steps basically involve physical removal of particles – large and small – from the sewage through filtration and sedimentation."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s83", "tokens": [{"t": "text", "v": "These are removed in stages; initially, "}, {"t": "cloze", "v": "floating debris"}, {"t": "text", "v": " is removed by sequential filtration."}], "blanks": ["floating debris"], "text": "These are removed in stages; initially, floating debris is removed by sequential filtration."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s84", "tokens": [{"t": "text", "v": "Then the grit (soil and small pebbles) are removed by "}, {"t": "cloze", "v": "sedimentation"}, {"t": "text", "v": "."}], "blanks": ["sedimentation"], "text": "Then the grit (soil and small pebbles) are removed by sedimentation."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s85", "tokens": [{"t": "text", "v": "All solids that settle form the "}, {"t": "cloze", "v": "primary sludge"}, {"t": "text", "v": " , and the supernatant forms the "}, {"t": "cloze", "v": "effluent"}, {"t": "text", "v": "."}], "blanks": ["primary sludge", "effluent"], "text": "All solids that settle form the primary sludge , and the supernatant forms the effluent."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s86", "tokens": [{"t": "text", "v": "The effluent from the primary settling tank is taken for "}, {"t": "cloze", "v": "secondary treatment"}, {"t": "text", "v": "."}], "blanks": ["secondary treatment"], "text": "The effluent from the primary settling tank is taken for secondary treatment."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s87", "tokens": [{"t": "cloze", "v": "Secondary treatment or Biological treatment"}, {"t": "text", "v": " : The primary effluent is passed into large "}, {"t": "cloze", "v": "aeration tanks"}, {"t": "text", "v": " (Figure 10.6) where it is constantly agitated mechanically and air is pumped into it."}], "blanks": ["Secondary treatment or Biological treatment", "aeration tanks"], "text": "Secondary treatment or Biological treatment : The primary effluent is passed into large aeration tanks (Figure 10.6) where it is constantly agitated mechanically and air is pumped into it."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s88", "tokens": [{"t": "text", "v": "This allows vigorous growth of useful "}, {"t": "cloze", "v": "aerobic microbes"}, {"t": "text", "v": " into "}, {"t": "cloze", "v": "flocs"}, {"t": "text", "v": " (masses of bacteria associated with fungal filaments to form mesh like structures)."}], "blanks": ["aerobic microbes", "flocs"], "text": "This allows vigorous growth of useful aerobic microbes into flocs (masses of bacteria associated with fungal filaments to form mesh like structures)."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s89", "tokens": [{"t": "text", "v": "While growing, these microbes consume the major part of the organic matter in the effluent."}], "blanks": [], "text": "While growing, these microbes consume the major part of the organic matter in the effluent."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s90", "tokens": [{"t": "text", "v": "This significantly reduces the "}, {"t": "cloze", "v": "BOD"}, {"t": "text", "v": " ("}, {"t": "cloze", "v": "biochemical oxygen demand"}, {"t": "text", "v": ") of the effluent."}], "blanks": ["BOD", "biochemical oxygen demand"], "text": "This significantly reduces the BOD (biochemical oxygen demand) of the effluent."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s91", "tokens": [{"t": "cloze", "v": "BOD"}, {"t": "text", "v": " refers to the amount of the oxygen that would be consumed if all the organic matter in one liter of water were oxidised by bacteria."}], "blanks": ["BOD"], "text": "BOD refers to the amount of the oxygen that would be consumed if all the organic matter in one liter of water were oxidised by bacteria."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s92", "tokens": [{"t": "text", "v": "The sewage water is treated till the BOD is reduced."}], "blanks": [], "text": "The sewage water is treated till the BOD is reduced."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s93", "tokens": [{"t": "text", "v": "The "}, {"t": "cloze", "v": "BOD"}, {"t": "text", "v": " test measures the rate of uptake of oxygen by micro-organisms in a sample of water and thus, indirectly, "}, {"t": "cloze", "v": "BOD"}, {"t": "text", "v": " is a measure of the organic matter present in the water."}], "blanks": ["BOD", "BOD"], "text": "The BOD test measures the rate of uptake of oxygen by micro-organisms in a sample of water and thus, indirectly, BOD is a measure of the organic matter present in the water."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s94", "tokens": [{"t": "text", "v": "The greater the "}, {"t": "cloze", "v": "BOD"}, {"t": "text", "v": " of waste water, more is its polluting potential."}], "blanks": ["BOD"], "text": "The greater the BOD of waste water, more is its polluting potential."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s95", "tokens": [{"t": "text", "v": "Once the BOD of sewage or waste water is reduced significantly, the effluent is then passed into a settling tank where the bacterial ‘"}, {"t": "cloze", "v": "flocs"}, {"t": "text", "v": "’ are allowed to sediment."}], "blanks": ["flocs"], "text": "Once the BOD of sewage or waste water is reduced significantly, the effluent is then passed into a settling tank where the bacterial ‘flocs’ are allowed to sediment."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s96", "tokens": [{"t": "text", "v": "This sediment is called "}, {"t": "cloze", "v": "activated sludge"}, {"t": "text", "v": " ."}], "blanks": ["activated sludge"], "text": "This sediment is called activated sludge ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s97", "tokens": [{"t": "text", "v": "A small part of the "}, {"t": "cloze", "v": "activated sludge"}, {"t": "text", "v": " is pumped back into the aeration tank to serve as the "}, {"t": "cloze", "v": "inoculum"}, {"t": "text", "v": "."}], "blanks": ["activated sludge", "inoculum"], "text": "A small part of the activated sludge is pumped back into the aeration tank to serve as the inoculum."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s98", "tokens": [{"t": "text", "v": "The remaining major part of the sludge is pumped into large tanks called "}, {"t": "cloze", "v": "anaerobic sludge digesters"}, {"t": "text", "v": " ."}], "blanks": ["anaerobic sludge digesters"], "text": "The remaining major part of the sludge is pumped into large tanks called anaerobic sludge digesters ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s99", "tokens": [{"t": "text", "v": "Here, other kinds of bacteria, which grow "}, {"t": "cloze", "v": "anaerobically"}, {"t": "text", "v": ", digest the bacteria and the fungi in the sludge."}], "blanks": ["anaerobically"], "text": "Here, other kinds of bacteria, which grow anaerobically, digest the bacteria and the fungi in the sludge."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s100", "tokens": [{"t": "text", "v": "During this digestion, bacteria produce a mixture of gases such as "}, {"t": "cloze", "v": "methane"}, {"t": "text", "v": ", "}, {"t": "cloze", "v": "hydrogen sulphide"}, {"t": "text", "v": " and carbon dioxide."}], "blanks": ["methane", "hydrogen sulphide"], "text": "During this digestion, bacteria produce a mixture of gases such as methane, hydrogen sulphide and carbon dioxide."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s101", "tokens": [{"t": "text", "v": "These gases form "}, {"t": "cloze", "v": "biogas"}, {"t": "text", "v": " and can be used as source of energy as it is inflammable."}], "blanks": ["biogas"], "text": "These gases form biogas and can be used as source of energy as it is inflammable."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s102", "tokens": [{"t": "text", "v": "The effluent from the "}, {"t": "cloze", "v": "secondary treatment plant"}, {"t": "text", "v": " is generally released into natural water bodies like rivers and streams."}], "blanks": ["secondary treatment plant"], "text": "The effluent from the secondary treatment plant is generally released into natural water bodies like rivers and streams."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s103", "tokens": [{"t": "text", "v": "An aerial view of such a plant is shown in Figure 10.7 ."}], "blanks": [], "text": "An aerial view of such a plant is shown in Figure 10.7 ."}, {"type": "caption", "content": "Figure 10.7 An aerial view of a sewage plant"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s104", "tokens": [{"t": "text", "v": "You can appreciate how microbes play a major role in treating millions of gallons of waste water everyday across the globe."}], "blanks": [], "text": "You can appreciate how microbes play a major role in treating millions of gallons of waste water everyday across the globe."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s105", "tokens": [{"t": "text", "v": "This methodology has been practiced for more than a century now, in almost all parts of the world."}], "blanks": [], "text": "This methodology has been practiced for more than a century now, in almost all parts of the world."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s106", "tokens": [{"t": "text", "v": "Till date, no man-made technology has been able to rival the microbial treatment of sewage."}], "blanks": [], "text": "Till date, no man-made technology has been able to rival the microbial treatment of sewage."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s107", "tokens": [{"t": "text", "v": "You are aware that due to increasing urbanisation, sewage is being produced in much larger quantities than ever before."}], "blanks": [], "text": "You are aware that due to increasing urbanisation, sewage is being produced in much larger quantities than ever before."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s108", "tokens": [{"t": "text", "v": "However the number of sewage treatment plants has not increased enough to treat such large quantities."}], "blanks": [], "text": "However the number of sewage treatment plants has not increased enough to treat such large quantities."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s109", "tokens": [{"t": "text", "v": "So the untreated sewage is often discharged directly into rivers leading to their pollution and increase in water-borne diseases."}], "blanks": [], "text": "So the untreated sewage is often discharged directly into rivers leading to their pollution and increase in water-borne diseases."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s110", "tokens": [{"t": "text", "v": "The "}, {"t": "cloze", "v": "Ministry of Environment and Forests"}, {"t": "text", "v": " has initiated "}, {"t": "cloze", "v": "Ganga Action Plan"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "Yamuna Action Plan"}, {"t": "text", "v": " to save these major rivers of our country from pollution."}], "blanks": ["Ministry of Environment and Forests", "Ganga Action Plan", "Yamuna Action Plan"], "text": "The Ministry of Environment and Forests has initiated Ganga Action Plan and Yamuna Action Plan to save these major rivers of our country from pollution."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s111", "tokens": [{"t": "text", "v": "Under these plans, it is proposed to build a large number of "}, {"t": "cloze", "v": "sewage treatment plants"}, {"t": "text", "v": " so that only treated sewage may be discharged in the rivers."}], "blanks": ["sewage treatment plants"], "text": "Under these plans, it is proposed to build a large number of sewage treatment plants so that only treated sewage may be discharged in the rivers."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s112", "tokens": [{"t": "text", "v": "A visit to a sewage treatment plant situated in any place near you would be a very interesting and educating experience."}], "blanks": [], "text": "A visit to a sewage treatment plant situated in any place near you would be a very interesting and educating experience."}, {"type": "h2", "content": "10.4 Microbes in Production of Biogas"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s113", "tokens": [{"t": "cloze", "v": "Biogas"}, {"t": "text", "v": " is a mixture of gases (containing predominantly "}, {"t": "cloze", "v": "methane"}, {"t": "text", "v": ") produced by the microbial activity and which may be used as fuel."}], "blanks": ["Biogas", "methane"], "text": "Biogas is a mixture of gases (containing predominantly methane) produced by the microbial activity and which may be used as fuel."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s114", "tokens": [{"t": "text", "v": "You have learnt that microbes produce different types of gaseous end-products during growth and metabolism."}], "blanks": [], "text": "You have learnt that microbes produce different types of gaseous end-products during growth and metabolism."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s115", "tokens": [{"t": "text", "v": "The type of the gas produced depends upon the microbes and the organic substrates they utilise."}], "blanks": [], "text": "The type of the gas produced depends upon the microbes and the organic substrates they utilise."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s116", "tokens": [{"t": "text", "v": "In the examples cited in relation to fermentation of dough, cheese making and production of beverages, the main gas produced was "}, {"t": "cloze", "v": "CO 2"}, {"t": "text", "v": ". ."}], "blanks": ["CO 2"], "text": "In the examples cited in relation to fermentation of dough, cheese making and production of beverages, the main gas produced was CO 2. ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s117", "tokens": [{"t": "text", "v": "However, certain bacteria, which grow "}, {"t": "cloze", "v": "anaerobically"}, {"t": "text", "v": " on cellulosic material, produce large amount of "}, {"t": "cloze", "v": "methane"}, {"t": "text", "v": " along with CO 2 and H 2 ."}], "blanks": ["anaerobically", "methane"], "text": "However, certain bacteria, which grow anaerobically on cellulosic material, produce large amount of methane along with CO 2 and H 2 ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s118", "tokens": [{"t": "text", "v": "These bacteria are collectively called "}, {"t": "cloze", "v": "methanogens"}, {"t": "text", "v": " , and one such common bacterium is "}, {"t": "cloze", "v": "Methanobacterium"}, {"t": "text", "v": " ."}], "blanks": ["methanogens", "Methanobacterium"], "text": "These bacteria are collectively called methanogens , and one such common bacterium is Methanobacterium ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s119", "tokens": [{"t": "text", "v": "These bacteria are commonly found in the "}, {"t": "cloze", "v": "anaerobic sludge"}, {"t": "text", "v": " during sewage treatment."}], "blanks": ["anaerobic sludge"], "text": "These bacteria are commonly found in the anaerobic sludge during sewage treatment."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s120", "tokens": [{"t": "text", "v": "These bacteria are also present in the "}, {"t": "cloze", "v": "rumen"}, {"t": "text", "v": " (a part of stomach) of cattle."}], "blanks": ["rumen"], "text": "These bacteria are also present in the rumen (a part of stomach) of cattle."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s121", "tokens": [{"t": "text", "v": "A lot of "}, {"t": "cloze", "v": "cellulosic material"}, {"t": "text", "v": " present in the food of cattle is also present in the rumen."}], "blanks": ["cellulosic material"], "text": "A lot of cellulosic material present in the food of cattle is also present in the rumen."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s122", "tokens": [{"t": "text", "v": "In rumen, these bacteria help in the breakdown of "}, {"t": "cloze", "v": "cellulose"}, {"t": "text", "v": " and play an important role in the nutrition of cattle."}], "blanks": ["cellulose"], "text": "In rumen, these bacteria help in the breakdown of cellulose and play an important role in the nutrition of cattle."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s123", "tokens": [{"t": "text", "v": "Do you think we, human beings, are able to digest the celluose present in our foods?"}], "blanks": [], "text": "Do you think we, human beings, are able to digest the celluose present in our foods?"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s124", "tokens": [{"t": "text", "v": "Thus, the excreta (dung) of cattle, commonly called "}, {"t": "cloze", "v": "gobar"}, {"t": "text", "v": " , is rich in these bacteria."}], "blanks": ["gobar"], "text": "Thus, the excreta (dung) of cattle, commonly called gobar , is rich in these bacteria."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s125", "tokens": [{"t": "text", "v": "Dung can be used for generation of biogas, commonly called "}, {"t": "cloze", "v": "gobar gas"}, {"t": "text", "v": " ."}], "blanks": ["gobar gas"], "text": "Dung can be used for generation of biogas, commonly called gobar gas ."}, {"type": "caption", "content": "Figure 10.8 A typical biogas plant"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s126", "tokens": [{"t": "text", "v": "The biogas plant consists of a concrete tank ("}, {"t": "cloze", "v": "10-15 feet"}, {"t": "text", "v": " deep) in which bio-wastes are collected and a slurry of dung is fed."}], "blanks": ["10-15 feet"], "text": "The biogas plant consists of a concrete tank (10-15 feet deep) in which bio-wastes are collected and a slurry of dung is fed."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s127", "tokens": [{"t": "text", "v": "A floating cover is placed over the slurry, which keeps on rising as the gas is produced in the tank due to the microbial activity."}], "blanks": [], "text": "A floating cover is placed over the slurry, which keeps on rising as the gas is produced in the tank due to the microbial activity."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s128", "tokens": [{"t": "text", "v": "The biogas plant has an outlet, which is connected to a pipe to supply biogas to nearby houses."}], "blanks": [], "text": "The biogas plant has an outlet, which is connected to a pipe to supply biogas to nearby houses."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s129", "tokens": [{"t": "text", "v": "The spent slurry is removed through another outlet and may be used as fert iliser."}], "blanks": [], "text": "The spent slurry is removed through another outlet and may be used as fert iliser."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s130", "tokens": [{"t": "text", "v": "Cattle dung is available in large quantities in rural areas where cattle are used for a variety of purposes."}], "blanks": [], "text": "Cattle dung is available in large quantities in rural areas where cattle are used for a variety of purposes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s131", "tokens": [{"t": "text", "v": "So biogas plants are more often built in rural areas."}], "blanks": [], "text": "So biogas plants are more often built in rural areas."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s132", "tokens": [{"t": "text", "v": "The biogas thus produced is used for cooking and lighting."}], "blanks": [], "text": "The biogas thus produced is used for cooking and lighting."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s133", "tokens": [{"t": "text", "v": "The picture of a biogas plant is shown in Figure 10.8."}], "blanks": [], "text": "The picture of a biogas plant is shown in Figure 10.8."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s134", "tokens": [{"t": "text", "v": "The technology of biogas production was developed in India mainly due to the efforts of "}, {"t": "cloze", "v": "Indian Agricultural Research Institute (IARI)"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "Khadi and Village Industries Commission (KVIC)"}, {"t": "text", "v": "."}], "blanks": ["Indian Agricultural Research Institute (IARI)", "Khadi and Village Industries Commission (KVIC)"], "text": "The technology of biogas production was developed in India mainly due to the efforts of Indian Agricultural Research Institute (IARI) and Khadi and Village Industries Commission (KVIC)."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s135", "tokens": [{"t": "text", "v": "If your school is situated in a village or near a village, it would be very interesting to enquire if there are any biogas plants nearby."}], "blanks": [], "text": "If your school is situated in a village or near a village, it would be very interesting to enquire if there are any biogas plants nearby."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s136", "tokens": [{"t": "text", "v": "Vis it the biogas plant and learn more about it from the people who are actually managing it."}], "blanks": [], "text": "Vis it the biogas plant and learn more about it from the people who are actually managing it."}, {"type": "h2", "content": "10.5 Microbes as Biocontrol Agents"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s137", "tokens": [{"t": "cloze", "v": "Biocontrol"}, {"t": "text", "v": " refers to the use of biological methods for controlling plant diseases and pests."}], "blanks": ["Biocontrol"], "text": "Biocontrol refers to the use of biological methods for controlling plant diseases and pests."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s138", "tokens": [{"t": "text", "v": "In modern society, these problems have been tackled increasingly by the use of chemicals – by use of insecticides and pesticides."}], "blanks": [], "text": "In modern society, these problems have been tackled increasingly by the use of chemicals – by use of insecticides and pesticides."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s139", "tokens": [{"t": "text", "v": "These chemicals are toxic and extremely harmful, to human beings and animals alike, and have been polluting our environment (soil, ground water), fruits, vegetables and crop plants."}], "blanks": [], "text": "These chemicals are toxic and extremely harmful, to human beings and animals alike, and have been polluting our environment (soil, ground water), fruits, vegetables and crop plants."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s140", "tokens": [{"t": "text", "v": "Our soil is also polluted through our use of weedicides to remove weeds."}], "blanks": [], "text": "Our soil is also polluted through our use of weedicides to remove weeds."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s141", "tokens": [{"t": "text", "v": "Biological control of pests and diseases: In agriculture, there is a method of controlling pests that relies on natural predation rather than introduced chemicals."}], "blanks": [], "text": "Biological control of pests and diseases: In agriculture, there is a method of controlling pests that relies on natural predation rather than introduced chemicals."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s142", "tokens": [{"t": "text", "v": "A key belief of the organic farmer is that biodiversity furthers health."}], "blanks": [], "text": "A key belief of the organic farmer is that biodiversity furthers health."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s143", "tokens": [{"t": "text", "v": "The more variety a landscape has, the more sustainable it is."}], "blanks": [], "text": "The more variety a landscape has, the more sustainable it is."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s144", "tokens": [{"t": "text", "v": "The organic farmer, therefore, works to create a system where the insects that are sometimes called pests are not eradicated, but instead are kept at manageable levels by a complex system of checks and balances within a living and vibrant ecosystem."}], "blanks": [], "text": "The organic farmer, therefore, works to create a system where the insects that are sometimes called pests are not eradicated, but instead are kept at manageable levels by a complex system of checks and balances within a living and vibrant ecosystem."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s145", "tokens": [{"t": "text", "v": "Contrary to the ‘conventional’ farming practices which often use chemical methods to kill both useful and harmful life forms indiscriminately, this is a holistic approach that seeks to develop an understanding of the webs of interaction between the myriad of organisms that constitute the field f auna and flora."}], "blanks": [], "text": "Contrary to the ‘conventional’ farming practices which often use chemical methods to kill both useful and harmful life forms indiscriminately, this is a holistic approach that seeks to develop an understanding of the webs of interaction between the myriad of organisms that constitute the field f auna and flora."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s146", "tokens": [{"t": "text", "v": "The organic farmer holds the view that the eradication of the creatures that are often described as pests is not only possible, but also undesirable, for without them the beneficial predatory and parasitic insects which depend upon them as food or hosts would not be able to survive."}], "blanks": [], "text": "The organic farmer holds the view that the eradication of the creatures that are often described as pests is not only possible, but also undesirable, for without them the beneficial predatory and parasitic insects which depend upon them as food or hosts would not be able to survive."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s147", "tokens": [{"t": "text", "v": "Thus, the use of biocontrol measures will greatly reduce our dependence on toxic chemicals and pesticides."}], "blanks": [], "text": "Thus, the use of biocontrol measures will greatly reduce our dependence on toxic chemicals and pesticides."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s148", "tokens": [{"t": "text", "v": "An important part of the biological farming approach is to become familiar with the various life forms that inhabit the field, predators as well as pests, and also their life cycles, patterns of feeding and the habitats that they prefer."}], "blanks": [], "text": "An important part of the biological farming approach is to become familiar with the various life forms that inhabit the field, predators as well as pests, and also their life cycles, patterns of feeding and the habitats that they prefer."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s149", "tokens": [{"t": "text", "v": "This will help develop appropriate means of biocontrol."}], "blanks": [], "text": "This will help develop appropriate means of biocontrol."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s150", "tokens": [{"t": "text", "v": "The very familiar beetle with red and black markings – the "}, {"t": "cloze", "v": "Ladybird"}, {"t": "text", "v": ", and "}, {"t": "cloze", "v": "Dragonflies"}, {"t": "text", "v": " are useful to get rid of aphids and mosquitoes, respectively."}], "blanks": ["Ladybird", "Dragonflies"], "text": "The very familiar beetle with red and black markings – the Ladybird, and Dragonflies are useful to get rid of aphids and mosquitoes, respectively."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s151", "tokens": [{"t": "text", "v": "An example of microbial biocontrol agents that can be introduced in order to control butterfly caterpillars is the bacteria "}, {"t": "cloze", "v": "Bacillus thuringiensis"}, {"t": "text", "v": " (often written as B t )."}], "blanks": ["Bacillus thuringiensis"], "text": "An example of microbial biocontrol agents that can be introduced in order to control butterfly caterpillars is the bacteria Bacillus thuringiensis (often written as B t )."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s152", "tokens": [{"t": "text", "v": "These are available in sachets as dried spores which are mixed with water and sprayed onto vulnerable plants such as brassicas and fruit trees, where these are eaten by the insect larvae."}], "blanks": [], "text": "These are available in sachets as dried spores which are mixed with water and sprayed onto vulnerable plants such as brassicas and fruit trees, where these are eaten by the insect larvae."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s153", "tokens": [{"t": "text", "v": "In the gut of the larvae, the toxin is released and the larvae get killed."}], "blanks": [], "text": "In the gut of the larvae, the toxin is released and the larvae get killed."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s154", "tokens": [{"t": "text", "v": "The bacterial disease will kill the caterpillars, but leave other insects unharmed."}], "blanks": [], "text": "The bacterial disease will kill the caterpillars, but leave other insects unharmed."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s155", "tokens": [{"t": "text", "v": "Because of the development of methods of genetic engineering in the last decade or so, the scientists have introduced "}, {"t": "cloze", "v": "B. thuringiensis"}, {"t": "text", "v": " toxin genes into plants."}], "blanks": ["B. thuringiensis"], "text": "Because of the development of methods of genetic engineering in the last decade or so, the scientists have introduced B. thuringiensis toxin genes into plants."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s156", "tokens": [{"t": "text", "v": "Such plants are resistant to attack by insect pests."}], "blanks": [], "text": "Such plants are resistant to attack by insect pests."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s157", "tokens": [{"t": "cloze", "v": "Bt-cotton"}, {"t": "text", "v": " is one such example, which is being cultivated in some states of our country."}], "blanks": ["Bt-cotton"], "text": "Bt-cotton is one such example, which is being cultivated in some states of our country."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s158", "tokens": [{"t": "text", "v": "You will learn more about this in chapter 12."}], "blanks": [], "text": "You will learn more about this in chapter 12."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s159", "tokens": [{"t": "text", "v": "A biological control being developed for use in the treatment of plant disease is the fungus "}, {"t": "cloze", "v": "Trichoderma"}, {"t": "text", "v": "."}], "blanks": ["Trichoderma"], "text": "A biological control being developed for use in the treatment of plant disease is the fungus Trichoderma."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s160", "tokens": [{"t": "cloze", "v": "Trichoderma"}, {"t": "text", "v": " species are free-living fungi that are very common in the root ecosystems."}], "blanks": ["Trichoderma"], "text": "Trichoderma species are free-living fungi that are very common in the root ecosystems."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s161", "tokens": [{"t": "text", "v": "They are effective biocontrol agents of several plant pathogens."}], "blanks": [], "text": "They are effective biocontrol agents of several plant pathogens."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s162", "tokens": [{"t": "cloze", "v": "Baculoviruses"}, {"t": "text", "v": " are pathogens that attack insects and other arthropods."}], "blanks": ["Baculoviruses"], "text": "Baculoviruses are pathogens that attack insects and other arthropods."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s163", "tokens": [{"t": "text", "v": "The majority of baculoviruses used as biological control agents are in the genus "}, {"t": "cloze", "v": "Nucleopolyhedrovirus"}, {"t": "text", "v": "."}], "blanks": ["Nucleopolyhedrovirus"], "text": "The majority of baculoviruses used as biological control agents are in the genus Nucleopolyhedrovirus."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s164", "tokens": [{"t": "text", "v": "These viruses are excellent candidates for "}, {"t": "cloze", "v": "species-specific"}, {"t": "text", "v": ", narrow spectrum insecticidal applications."}], "blanks": ["species-specific"], "text": "These viruses are excellent candidates for species-specific, narrow spectrum insecticidal applications."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s165", "tokens": [{"t": "text", "v": "They have been shown to have no negative impacts on plants, mammals, birds, fish or even on non-target insects."}], "blanks": [], "text": "They have been shown to have no negative impacts on plants, mammals, birds, fish or even on non-target insects."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s166", "tokens": [{"t": "text", "v": "This is especially desirable when beneficial insects are being conserved to aid in an overall "}, {"t": "cloze", "v": "integrated pest management (IPM)"}, {"t": "text", "v": " programme, or when an ecologically sensitive area is being treated."}], "blanks": ["integrated pest management (IPM)"], "text": "This is especially desirable when beneficial insects are being conserved to aid in an overall integrated pest management (IPM) programme, or when an ecologically sensitive area is being treated."}, {"type": "h2", "content": "10.6 Microbes as Biofertilisers"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s167", "tokens": [{"t": "text", "v": "With our present day life styles environmental pollution is a major cause of concern."}], "blanks": [], "text": "With our present day life styles environmental pollution is a major cause of concern."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s168", "tokens": [{"t": "text", "v": "The use of the chemical fertilisers to meet the ever-increasing demand of agricultural produce has contributed significantly to this pollution."}], "blanks": [], "text": "The use of the chemical fertilisers to meet the ever-increasing demand of agricultural produce has contributed significantly to this pollution."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s169", "tokens": [{"t": "text", "v": "Of course, we have now realised that there are problems associated with the overuse of chemical fertilisers and there is a large pressure to switch to organic farming – the use of "}, {"t": "cloze", "v": "biofertilisers"}, {"t": "text", "v": " ."}], "blanks": ["biofertilisers"], "text": "Of course, we have now realised that there are problems associated with the overuse of chemical fertilisers and there is a large pressure to switch to organic farming – the use of biofertilisers ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s170", "tokens": [{"t": "cloze", "v": "Biofertilisers"}, {"t": "text", "v": " are organisms that enrich the nutrient quality of the soil."}], "blanks": ["Biofertilisers"], "text": "Biofertilisers are organisms that enrich the nutrient quality of the soil."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s171", "tokens": [{"t": "text", "v": "The main sources of biofertilisers are "}, {"t": "cloze", "v": "bacteria, fungi and cyanobacteria"}, {"t": "text", "v": "."}], "blanks": ["bacteria, fungi and cyanobacteria"], "text": "The main sources of biofertilisers are bacteria, fungi and cyanobacteria."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s172", "tokens": [{"t": "text", "v": "You have studied about the nodules on the roots of leguminous plants formed by the symbiotic association of "}, {"t": "cloze", "v": "Rhizobium"}, {"t": "text", "v": " ."}], "blanks": ["Rhizobium"], "text": "You have studied about the nodules on the roots of leguminous plants formed by the symbiotic association of Rhizobium ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s173", "tokens": [{"t": "text", "v": "These bacteria fix atmospheric nitrogen into organic forms, which is used by the plant as nutrient."}], "blanks": [], "text": "These bacteria fix atmospheric nitrogen into organic forms, which is used by the plant as nutrient."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s174", "tokens": [{"t": "text", "v": "Other bacteria can fix atmospheric nitrogen while free-living in the soil (examples "}, {"t": "cloze", "v": "Azospirillum"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "Azotobacter"}, {"t": "text", "v": " ), thus enriching the nitrogen content of the soil."}], "blanks": ["Azospirillum", "Azotobacter"], "text": "Other bacteria can fix atmospheric nitrogen while free-living in the soil (examples Azospirillum and Azotobacter ), thus enriching the nitrogen content of the soil."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s175", "tokens": [{"t": "text", "v": "Fungi are also known to form symbiotic associations with plants ( "}, {"t": "cloze", "v": "mycorrhiza"}, {"t": "text", "v": " )."}], "blanks": ["mycorrhiza"], "text": "Fungi are also known to form symbiotic associations with plants ( mycorrhiza )."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s176", "tokens": [{"t": "text", "v": "Many members of the genus "}, {"t": "cloze", "v": "Glomus"}, {"t": "text", "v": " form "}, {"t": "cloze", "v": "mycorrhiza"}, {"t": "text", "v": "."}], "blanks": ["Glomus", "mycorrhiza"], "text": "Many members of the genus Glomus form mycorrhiza."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s177", "tokens": [{"t": "text", "v": "The fungal symbiont in these associations absorbs "}, {"t": "cloze", "v": "phosphorus"}, {"t": "text", "v": " from soil and passes it to the plant."}], "blanks": ["phosphorus"], "text": "The fungal symbiont in these associations absorbs phosphorus from soil and passes it to the plant."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s178", "tokens": [{"t": "text", "v": "Plants having such associations show other benefits also, such as resistance to root-borne pathogens, tolerance to salinity and drought, and an overall increase in plant growth and development."}], "blanks": [], "text": "Plants having such associations show other benefits also, such as resistance to root-borne pathogens, tolerance to salinity and drought, and an overall increase in plant growth and development."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s179", "tokens": [{"t": "text", "v": "Can you tell what advantage the fungus derives from this association?"}], "blanks": [], "text": "Can you tell what advantage the fungus derives from this association?"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s180", "tokens": [{"t": "text", "v": "Cyanobacteria are autotrophic microbes widely distributed in aquatic and terrestrial environments many of which can fix atmospheric nitrogen, e.g. "}, {"t": "cloze", "v": "Anabaena"}, {"t": "text", "v": " , "}, {"t": "cloze", "v": "Nostoc"}, {"t": "text", "v": " , Oscillatoria, etc. In paddy fields, cyanobacteria serve as an important biofertiliser."}], "blanks": ["Anabaena", "Nostoc"], "text": "Cyanobacteria are autotrophic microbes widely distributed in aquatic and terrestrial environments many of which can fix atmospheric nitrogen, e.g. Anabaena , Nostoc , Oscillatoria, etc. In paddy fields, cyanobacteria serve as an important biofertiliser."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s181", "tokens": [{"t": "text", "v": "Blue green algae also add organic matter to the soil and increase its fertility."}], "blanks": [], "text": "Blue green algae also add organic matter to the soil and increase its fertility."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s182", "tokens": [{"t": "text", "v": "Currently, in our country, a number of biofertilisers are available commercially in the market and farmers use these regularly in their fields to replenish soil nutrients and to reduce dependence on chemical fertilisers."}], "blanks": [], "text": "Currently, in our country, a number of biofertilisers are available commercially in the market and farmers use these regularly in their fields to replenish soil nutrients and to reduce dependence on chemical fertilisers."}, {"type": "caption", "content": "SUMMARY"}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s183", "tokens": [{"t": "text", "v": "Microbes are a very important component of life on earth."}], "blanks": [], "text": "Microbes are a very important component of life on earth."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s184", "tokens": [{"t": "text", "v": "Not all microbes are pathogenic. Many microbes are very useful to human beings."}], "blanks": [], "text": "Not all microbes are pathogenic. Many microbes are very useful to human beings."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s185", "tokens": [{"t": "text", "v": "We use microbes and microbially derived products almost every day."}], "blanks": [], "text": "We use microbes and microbially derived products almost every day."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s186", "tokens": [{"t": "text", "v": "Bacteria called "}, {"t": "cloze", "v": "lactic acid bacteria (LAB)"}, {"t": "text", "v": " grow in milk to convert it into curd."}], "blanks": ["lactic acid bacteria (LAB)"], "text": "Bacteria called lactic acid bacteria (LAB) grow in milk to convert it into curd."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s187", "tokens": [{"t": "text", "v": "The dough, which is used to make bread, is fermented by yeast called "}, {"t": "cloze", "v": "Saccharomyces cerevisiae"}, {"t": "text", "v": " ."}], "blanks": ["Saccharomyces cerevisiae"], "text": "The dough, which is used to make bread, is fermented by yeast called Saccharomyces cerevisiae ."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s188", "tokens": [{"t": "text", "v": "Certain dishes such as "}, {"t": "cloze", "v": "idli"}, {"t": "text", "v": " and "}, {"t": "cloze", "v": "dosa"}, {"t": "text", "v": " , are made from dough fermented by microbes."}], "blanks": ["idli", "dosa"], "text": "Certain dishes such as idli and dosa , are made from dough fermented by microbes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s189", "tokens": [{"t": "text", "v": "Bacteria and fungi are used to impart particular texture, taste and flavor to cheese."}], "blanks": [], "text": "Bacteria and fungi are used to impart particular texture, taste and flavor to cheese."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s190", "tokens": [{"t": "text", "v": "Microbes are used to produce industrial products like "}, {"t": "cloze", "v": "lactic acid"}, {"t": "text", "v": ", "}, {"t": "cloze", "v": "acetic acid"}, {"t": "text", "v": " and alcohol, which are used in a variety of processes in the industry."}], "blanks": ["lactic acid", "acetic acid"], "text": "Microbes are used to produce industrial products like lactic acid, acetic acid and alcohol, which are used in a variety of processes in the industry."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s191", "tokens": [{"t": "text", "v": "Antibiotics like "}, {"t": "cloze", "v": "penicillins"}, {"t": "text", "v": " produced by useful microbes are used to kill disease-causing harmful microbes."}], "blanks": ["penicillins"], "text": "Antibiotics like penicillins produced by useful microbes are used to kill disease-causing harmful microbes."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s192", "tokens": [{"t": "text", "v": "Antibiotics have played a major role in controlling infectious diseases like "}, {"t": "cloze", "v": "diphtheria"}, {"t": "text", "v": ", whooping cough and "}, {"t": "cloze", "v": "pneumonia"}, {"t": "text", "v": "."}], "blanks": ["diphtheria", "pneumonia"], "text": "Antibiotics have played a major role in controlling infectious diseases like diphtheria, whooping cough and pneumonia."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s193", "tokens": [{"t": "text", "v": "For more than a hundred years, microbes are being used to treat sewage (waste water) by the process of "}, {"t": "cloze", "v": "activated sludge"}, {"t": "text", "v": " formation and this helps in recycling of water in nature."}], "blanks": ["activated sludge"], "text": "For more than a hundred years, microbes are being used to treat sewage (waste water) by the process of activated sludge formation and this helps in recycling of water in nature."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s194", "tokens": [{"t": "cloze", "v": "Methanogens"}, {"t": "text", "v": " produce "}, {"t": "cloze", "v": "methane"}, {"t": "text", "v": " (biogas) while degrading plant waste."}], "blanks": ["Methanogens", "methane"], "text": "Methanogens produce methane (biogas) while degrading plant waste."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s195", "tokens": [{"t": "text", "v": "Biogas produced by microbes is used as a source of energy in rural areas."}], "blanks": [], "text": "Biogas produced by microbes is used as a source of energy in rural areas."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s196", "tokens": [{"t": "text", "v": "Microbes can also be used to kill harmful pests, a process called as "}, {"t": "cloze", "v": "biocontrol"}, {"t": "text", "v": "."}], "blanks": ["biocontrol"], "text": "Microbes can also be used to kill harmful pests, a process called as biocontrol."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s197", "tokens": [{"t": "text", "v": "The biocontrol measures help us to avoid heavy use of toxic pesticides for controlling pests."}], "blanks": [], "text": "The biocontrol measures help us to avoid heavy use of toxic pesticides for controlling pests."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s198", "tokens": [{"t": "text", "v": "There is a need these days to push for use of biofertilisers in place of chemical fertilisers."}], "blanks": [], "text": "There is a need these days to push for use of biofertilisers in place of chemical fertilisers."}, {"type": "sentence", "id": "Microbes_in_Human_Welfare_Zoo_s199", "tokens": [{"t": "text", "v": "It is clear from the diverse uses human beings have put microbes to that they play an important role in the welfare of human society."}], "blanks": [], "text": "It is clear from the diverse uses human beings have put microbes to that they play an important role in the welfare of human society."}]};
